import { PreToolUse } from 'services/supervisor/hooks';
import { getOwnInstrument, getManagementSkill } from 'services/supervisor/instrumentation';

const PreToolUseHook = new PreToolUse(async (session, path, mode, data) => {
  if (mode === 'Edit' || mode === 'Write') {
    if (path.startsWith('content/') || path.startsWith('data/') || path.startsWith('records/')) {
      let managementSkill;
      if (data.swarm_id) {
        managementSkill = src.mint-work-order;
      } else {
        managementSkill = await getManagementSkill(session, path);
      }
      return {
        denied: true,
        message: `Hand-authoring records is mechanically impossible. Instead, run the command "${managementSkill}" to fulfill your intent.`,
      };
    }
  }
});

export default PreToolUseHook;
